from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    """
    Abstract base class for sorting algorithms.
    """

    def __init__(self):
        pass

    @abstractmethod
    def sort(self, data):
        pass

    def compare(self, a, b):
        raise NotImplementedError("Comparison method must be implemented in subclasses.")

    def swap(self, a, b):
        raise NotImplementedError("Swap method must be implemented in subclasses.")


class BubbleSort(SortAlgorithm):
    """
    Implementation of Bubble Sort algorithm.
    """

    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n-i-1):
                if data[j] > data[j+1]:
                    data[j], data[j+1] = data[j+1], data[j]
        return

    def compare(self, a, b):
        return a > b  # Example comparison - can be customized


class SelectionSort(SortAlgorithm):
    """
    Implementation of Selection Sort algorithm.
    """

    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_index = i
            for j in range(i+1, n):
                if data[j] < data[min_index]:
                    min_index = j
            data[i], data[min_index] = data[min_index], data[i]
        return

    def compare(self, a, b):
        return a < b  # Example comparison - can be customized


if __name__ == '__main__':
    # Example Usage
    data = [5, 2, 8, 1, 9, 4]

    bubble_sort = BubbleSort()
    bubble_sort.sort(data)
    print("Bubble Sort:", bubble_sort.sort(data))

    selection_sort = SelectionSort()
    selection_sort.sort(data)
    print("Selection Sort:", selection_sort.sort(data))
